+            visit(irCatchNode, writeScope.newTryScope(tryBeginLabel, tryEndLabel, catchJumpLabel));
+        }
+
+        if (irTryNode.getBlockNode().doAllEscape() == false || catchNodes.size() > 1) {
+            methodWriter.mark(catchesEndLabel);
+        }
+    }
